def min_edit_distance(w1: str, w2: str) -> int:
    dp = list(range(len(w2) + 1))
    for i, c1 in enumerate(w1, 1):
        ndp = [i]
        for j, c2 in enumerate(w2, 1):
            ndp.append(dp[j - 1] if c1 == c2 else 1 + min(ndp[-1], dp[j], dp[j - 1]))
        dp = ndp
    return dp[-1]
```

