class EventBus:
    def __init__(self):
        self.subs = {}

    def subscribe(self, event: str, fn):
        self.subs.setdefault(event, [])
        self.subs[event].append(fn)

    def publish(self, event: str, data) -> list:
        return [fn(data) for fn in self.subs.get(event, [])]
